//! WS2812 matrix over the PIOC programmable I/O core (V3F).
//!
//! The RGB bits are generated by WCH's RGB1W firmware, which is loaded into
//! the PIOC program SRAM; the HAL only implements the host handshake. A single
//! LED fits the shared SFR window and uses the short command, while the 64-LED
//! matrix frame has to go through program RAM — and once that happens the image
//! tail is gone, so the driver stays on the RAM path for the rest of the run.
//!
//! # What it shows
//!
//! 1. One red LED through the SFR path, the vendor default command.
//! 2. A throughput benchmark: colour-wheel frames of 64, 300 and 1024 pixels,
//!    back to back, then one bar per result (one pixel per 10 fps).
//! 3. A single white pixel walking the panel in visual order, and a level
//!    meter, both at full speed.
//! 4. A rainbow that stays on screen: one wheel turn across the panel, one hue
//!    step per frame.
//!
//! A 64-LED frame is 192 payload bytes, well inside the 3072-byte RAM window,
//! and every effect runs at 20 Hz.
//!
//! # Pin
//!
//! PIOC IO0 can come out on four CH32H417 pins: `PB8`/AF5, `PC1`/AF7,
//! `PE3`/AF5 and `PF12`/AF3 (ch32-data `data/family/CH32H4.yaml`). The vendor
//! 1-Wire example uses `PC1`, which is also `ETH_MDIO` and is not routed out on
//! every board, so the pin is a cargo feature:
//!
//! ```text
//! --features pioc-io0-pb8    # also USBHS D+ / SWCLK
//! --features pioc-io0-pc1    # default; also ETH_MDIO
//! --features pioc-io0-pe3    # also USBSS SERDES_TXP, USART5_TX/AF11
//! --features pioc-io0-pf12   # VIO18 domain: only 1.8 V, will not drive a
//!                            # 5 V WS2812
//! ```
//!
//! ```text
//! cargo xtask flash --example pioc_ws2812 --v3f-only --features pioc-io0-pe3
//! ```

#![no_std]
#![no_main]

use ch32_hal as hal;
use embassy_executor::Spawner;
use embassy_time::{Instant, Timer};
use hal::pioc::Pioc;
use panic_halt as _;
use pioc_programs::ws2812::{bit_cycles_for_hz, ColorOrder, Config, OutputPin, Rgb8, Storage, Ws2812};
use pioc_programs::Firmware;

/// WCH RGB1W, translated from the CH32H417 EVT
/// (`EXAM/PIOC/PIOC_1_Wire/Common/Asm/RGB1W.ASM`) into the canonical dialect.
/// The delay loops are assembled for 100 MHz, so the SFR path may only be used
/// when the PIOC clock really is 100 MHz.
const FIRMWARE: Firmware = Firmware {
    words: pioc_proc::pioc_file_canonical!("firmware/rgb1w-100m.pio"),
    sfr_bit_cycles: 117,
};

/// Delay between frames of the quick effects. Zero runs them as fast as the
/// PIOC can hand the panel data, which is the point of the benchmark.
const FRAME_MS: u64 = 0;

/// Delay between rainbow frames. Fast updates blend into a flicker, so the
/// closing effect trades refresh rate for a smooth drift.
const RAINBOW_MS: u64 = 50;

/// Payloads the throughput benchmark feeds back to back, in pixels. 64 is this
/// panel, 300 matches the strip case, 1024 is the whole 3072-byte RAM window.
const BENCH_PIXELS: [usize; 3] = [64, 300, 1024];

/// Frames per benchmark point.
const BENCH_FRAMES: u32 = 100;

/// Measured frames per second per [`BENCH_PIXELS`] entry.
static mut BENCH_FPS: [u32; BENCH_PIXELS.len()] = [0; BENCH_PIXELS.len()];

/// Frame buffer for the benchmark; the largest payload would not fit on the
/// stack comfortably next to the executor.
static mut BENCH_FRAME: [Rgb8; 1024] = [Rgb8::new(0, 0, 0); 1024];

#[path = "../panel.rs"]
mod panel;

use panel::{clear, index, meter, wheel, HEIGHT, LEVEL, PIXELS, WIDTH};

#[embassy_executor::main(entry = "qingke_rt::entry")]
async fn main(_spawner: Spawner) -> ! {
    let p = hal::init(hal::Config {
        rcc: hal::rcc::Config::with_sysclk_400m_v5f_400m_v3f_100m_hse(),
        ..Default::default()
    });

    let bit_cycles = bit_cycles_for_hz(hal::rcc::clocks().hclk.0)
        .expect("a 100 MHz PIOC clock must give a representable WS2812 bit");
    assert_eq!(bit_cycles, 117, "RGB1W's 1.17 us bit at 100 MHz");

    // `PE3` is the default because it is a 3.3 V pin and is exposed on the
    // boards at hand; the others are one feature away.
    #[cfg(not(any(feature = "pioc-io0-pb8", feature = "pioc-io0-pc1", feature = "pioc-io0-pf12")))]
    let io0 = p.PE3;
    #[cfg(feature = "pioc-io0-pb8")]
    let io0 = p.PB8;
    #[cfg(feature = "pioc-io0-pc1")]
    let io0 = p.PC1;
    #[cfg(feature = "pioc-io0-pf12")]
    let io0 = p.PF12;

    let mut pioc = Pioc::new_io0(p.PIOC, io0);
    pioc.load_image(FIRMWARE.words)
        .expect("RGB1W is 1152 bytes, well inside the 4 KiB program SRAM");

    let mut ws = Ws2812::new(
        pioc,
        FIRMWARE,
        Config {
            output: OutputPin::Io0,
            storage: Storage::Auto,
            bit_cycles,
        },
    );

    // Effect 1: the SFR path, one red LED. Only the first frame of the program
    // can use it: the matrix frames below overwrite the image tail.
    ws.write_rgb(&[Rgb8::new(0x40, 0, 0)], ColorOrder::Grb)
        .await
        .expect("one LED over the SFR path");
    Timer::after_millis(800).await;

    // Throughput benchmark: hand the panel payloads back to back, with no
    // delay and no drawing work between frames, so the number is the cost of
    // the PIOC transfer itself.
    for (slot, &pixels) in BENCH_PIXELS.iter().enumerate() {
        let frame: &mut [Rgb8; 1024] = unsafe { &mut *core::ptr::addr_of_mut!(BENCH_FRAME) };
        // A colour wheel along the strip: it reads as a deliberate test image
        // rather than as a frame that went wrong, and a torn transfer leaves a
        // visible seam in it.
        for (index, color) in frame.iter_mut().take(pixels).enumerate() {
            *color = wheel((index * 96 / pixels) as u32);
        }
        // One untimed frame first: the first transfer after an image reload is
        // slower and would skew the average.
        ws.write_rgb(&frame[..pixels], ColorOrder::Grb)
            .await
            .expect("benchmark warm-up");

        let start = Instant::now();
        for _ in 0..BENCH_FRAMES {
            ws.write_rgb(&frame[..pixels], ColorOrder::Grb)
                .await
                .expect("benchmark frame");
        }
        let elapsed = start.elapsed();
        let us = (elapsed.as_micros() / u64::from(BENCH_FRAMES)) as u32;
        let fps = if us == 0 { 0 } else { 1_000_000 / us };
        unsafe { BENCH_FPS[slot] = fps };
    }

    // Show what was measured: one bar per payload size, one pixel per 10 fps,
    // 64 pixels covering up to 640 fps. The expected heights are 55 (64
    // pixels), 11 (300) and 3 (1024); see the module docs for the arithmetic.
    for slot in 0..BENCH_PIXELS.len() {
        let fps = unsafe { BENCH_FPS[slot] };
        let level = ((fps / 10) as usize).min(PIXELS);
        ws.write_rgb(&meter(level), ColorOrder::Grb)
            .await
            .expect("benchmark result");
        Timer::after_millis(1500).await;
    }

    // One pass of the quick effects, then settle on the rainbow: at full speed
    // every frame replaces the last one long before the eye can integrate it,
    // which reads as flicker rather than motion.

    // A white pixel walking in visual order. On a zigzag panel it sweeps left to
    // right along a row and right to left along the next, which is the layout
    // itself and not a glitch.
    for step in 0..PIXELS {
        let mut frame = clear();
        frame[index(step % WIDTH, step / WIDTH)] = Rgb8::new(LEVEL, LEVEL, LEVEL);
        ws.write_rgb(&frame, ColorOrder::Grb).await.expect("walking pixel");
        Timer::after_millis(FRAME_MS).await;
    }

    // A level meter that fills to full and drains again, in the same visual
    // order, with a white head marking the tip.
    for _ in 0..2 {
        for level in 0..=PIXELS {
            ws.write_rgb(&meter(level), ColorOrder::Grb).await.expect("level meter");
            Timer::after_millis(FRAME_MS).await;
        }
        for level in (0..PIXELS).rev() {
            ws.write_rgb(&meter(level), ColorOrder::Grb).await.expect("level meter");
            Timer::after_millis(FRAME_MS).await;
        }
    }

    // The rainbow, and the effect it ends on.
    //
    // The hue covers one full turn across the panel, so neighbouring pixels
    // differ by about 1.5 of the 96 steps and the gradient reads as continuous.
    // The phase moves one step per frame at 20 fps: a full turn takes about
    // five seconds, slow enough that the change is a drift and not a flash.
    let mut phase = 0u32;
    loop {
        let mut frame = clear();
        for y in 0..HEIGHT {
            for x in 0..WIDTH {
                // Both axes have to reach the modulus, otherwise the hue
                // aliases into bands: `(x * 8 + y) * 6 % 96` only depends on `y`
                // and the parity of `x`, which draws whole rows in one colour.
                let hue = (phase + ((x * HEIGHT + y) * 96 / PIXELS) as u32) % 96;
                frame[index(x, y)] = wheel(hue);
            }
        }
        ws.write_rgb(&frame, ColorOrder::Grb).await.expect("rainbow");
        phase = (phase + 1) % 96;
        Timer::after_millis(RAINBOW_MS).await;
    }
}
